from calendar import monthrange
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    kind, interval = parts[0], int(parts[1])
    weekdays = {name: i for i, name in enumerate(
        ("MO", "TU", "WE", "TH", "FR", "SA", "SU")
    )}

    def candidates():
        if kind == "DAILY":
            current = start_date
            while True:
                yield current
                current += timedelta(days=interval)

        elif kind == "WEEKLY":
            offsets = sorted(weekdays[name] for name in parts[2].split(","))
            monday = start_date - timedelta(days=start_date.weekday())
            while True:
                for offset in offsets:
                    yield monday + timedelta(days=offset)
                monday += timedelta(weeks=interval)

        elif kind == "MONTHLY":
            month_index = start_date.year * 12 + start_date.month - 1
            number = int(parts[2])
            target_weekday = weekdays[parts[3]] if len(parts) == 4 else None

            while True:
                year, month_zero = divmod(month_index, 12)
                month = month_zero + 1
                first_weekday, days_in_month = monthrange(year, month)

                if target_weekday is None:
                    day = days_in_month if number == -1 else number
                elif number == -1:
                    last_weekday = (first_weekday + days_in_month - 1) % 7
                    day = days_in_month - (last_weekday - target_weekday) % 7
                else:
                    day = (
                        1
                        + (target_weekday - first_weekday) % 7
                        + 7 * (number - 1)
                    )

                if day <= days_in_month:
                    yield date(year, month, day)
                month_index += interval

        elif kind == "YEARLY":
            month, day = map(int, parts[2].split("-"))
            year = start_date.year
            while True:
                if day <= monthrange(year, month)[1]:
                    yield date(year, month, day)
                year += interval

    result = []
    for candidate in candidates():
        if candidate >= start_date:
            result.append(candidate.isoformat())
            if len(result) == count:
                return result
